from collections import Counter

def _runs(vals, bg):
    found=[]
    i=0
    while i<len(vals):
        if vals[i]==bg:
            i+=1; continue
        j=i+1
        while j<len(vals) and vals[j]==vals[i]: j+=1
        if j-i>=2:
            found.append((i,j,vals[i]))
        i=j
    return found

def transform(grid):
    src=[row[:] for row in grid]
    out=[row[:] for row in grid]
    h,w=len(src),len(src[0])
    bg=Counter(v for row in src for v in row).most_common(1)[0][0]
    dots=[(r,c,src[r][c]) for r in range(1,h-1) for c in range(1,w-1) if src[r][c]!=bg]
    if not dots: return out
    ink=Counter(v for _,_,v in dots).most_common(1)[0][0]
    sides={
        'top':_runs(src[0],bg),
        'bottom':_runs(src[-1],bg),
        'left':_runs([src[r][0] for r in range(h)],bg),
        'right':_runs([src[r][-1] for r in range(h)],bg),
    }
    pairs=[]
    for a,b,axis in [('top','bottom','col'),('left','right','row')]:
        for x in sides[a]:
            for y in sides[b]:
                if x[1]-x[0]==y[1]-y[0]: pairs.append((a,x,b,y,axis))
    for s1,x,s2,y,axis in pairs:
        length=x[1]-x[0]
        offsets=set()
        for r,c,_ in dots:
            q=c if axis=='col' else r
            if x[0]<=q<x[1]: offsets.add(q-x[0])
            if y[0]<=q<y[1]: offsets.add(q-y[0])
        for side,bar in ((s1,x),(s2,y)):
            for off in offsets:
                if off>=length: continue
                k=bar[0]+off
                if side=='top': r,c,dr,dc=0,k,1,0
                elif side=='bottom': r,c,dr,dc=h-1,k,-1,0
                elif side=='left': r,c,dr,dc=k,0,0,1
                else: r,c,dr,dc=k,w-1,0,-1
                r+=dr; c+=dc
                while 0<=r<h and 0<=c<w:
                    if src[r][c]==bg:
                        out[r][c]=ink
                    else:
                        if 0<r<h-1 and 0<c<w-1: out[r][c]=4
                        break
                    r+=dr; c+=dc
    return out

